function slidesFromBody(body) {
    const text = lyricsToPlainText(body);
    const blocks = text
        .split(/\n\s*\n+/)
        .map(value => value.trim())
        .filter(Boolean);
    return blocks.map(value => ({
        text: value,
        isChorus: false,
        chorusAfter: false,
    }));
}

